head.script:
//
/* v10.78 · Song ngữ trang chủ: ?lang=en | ?lang=vi → localStorage lh-lang (chung với game) → tiếng Việt.
   Chữ của trang đổi lúc hiện ra; bài viết, tên người chơi giữ nguyên. Nút có data-home-lang đổi ngôn ngữ. */
(function(){
 var lang='vi';try{var m=/[?&#]lang=(en|vi)\b/i.exec(location.search+location.hash);if(m){lang=m[1].toLowerCase();localStorage.setItem('lh-lang',lang);}else lang=localStorage.getItem('lh-lang')||'vi';}catch(e){}
 if(lang!=='en')lang='vi';var EN=lang==='en';window.LH_HOME_LANG=lang;window.LH_HOME_LOC=EN?'en-US':(window.LH_HOME_LOC||'vi-VN');
 var GAME='https://www.ikyna.com/p/lu-hanh.html';
 function fixLinks(root){(root||document).querySelectorAll('a[href*="/p/lu-hanh.html"]').forEach(function(a){if(a.hasAttribute('data-home-lang'))return;var u=new URL(a.href,location.href);u.searchParams.set('lang',lang);a.href=u.toString();});}
 function paintBtns(root){(root||document).querySelectorAll('[data-home-lang]').forEach(function(b){var to=EN?'vi':'en';b.setAttribute('data-home-lang',to);
   var isPlay=b.classList.contains('lh-play-en'),u=new URL(isPlay?GAME:location.href,location.href);u.searchParams.set('lang',to);u.hash=isPlay?'':u.hash;b.href=u.toString();
   var t=b.querySelector('.lh-lang-t')||b;t.textContent=isPlay?(EN?'Chơi bằng tiếng Việt':'Play in English'):(EN?'Tiếng Việt':'English');b.setAttribute('lang',EN?'vi':'en');});}
 document.addEventListener('click',function(e){var b=e.target&&e.target.closest&&e.target.closest('[data-home-lang]');if(!b)return;try{localStorage.setItem('lh-lang',b.getAttribute('data-home-lang'));}catch(x){}},true);
 function boot(){fixLinks();paintBtns();if(EN)startTr();new MutationObserver(function(l){l.forEach(function(r){r.addedNodes.forEach(function(n){if(n.nodeType===1){fixLinks(n.parentNode||n);}});});}).observe(document.body,{childList:true,subtree:true});}
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot);else boot();
 if(!EN)return;
 var D={"Tin tức":"News","Sự kiện":"Events","Hướng dẫn":"Guides","Cốt truyện":"Story","Bài viết":"Posts","Nhật ký":"Journal","Thử tải lại":"Try again","Chưa có bài viết trong mục":"No posts yet in","Nhật ký đang chờ câu chuyện đầu tiên.":"The journal is waiting for its first story.","Chưa có bài viết":"No posts yet","bài":"posts","mới nhất":"latest","Đang tải bài viết…":"Loading posts…","Đang tải":"Loading","bài viết mới":"new posts","Chưa tải được bài viết. Thử lại hoặc mở danh sách bên dưới.":"Couldn't load posts. Try again or open the list below.","Kết nối tạm gián đoạn":"Connection interrupted","Cấp":"Level","hồng ngọc":"rubies","vàng":"gold","Bảng vàng còn trống. Hãy là lữ khách đầu tiên ghi tên!":"The hall of fame is empty. Be the first traveler to sign it!","Nhân vật":"Character","Vàng":"Gold","Hồng ngọc":"Rubies","lữ khách trên máy chủ · cập nhật":"travelers on the server · updated","Đang mở bảng vàng…":"Opening the hall of fame…","Chưa lấy được bảng xếp hạng từ máy chủ game.":"Couldn't fetch the rankings from the game server.","Trang chủ":"Home","Xếp hạng":"Rankings","Liên hệ":"Contact","Vào game":"Play","iKyNa · Nhập vai phiêu lưu":"iKyNa · Adventure RPG","Rời làng Thanh Mộc, băng qua sa mạc, núi tuyết và những hang sâu chưa ai đi hết. Một thanh kiếm, một cánh cung hay một cuốn sách phép — hành trình là của bạn.":"Leave Thanh Mộc Village, cross deserts, snowy peaks and caves no one has fully explored. A sword, a bow or a book of spells — the journey is yours.","Xem lối chơi":"See how to play","Đánh gần":"Melee","Đánh xa":"Ranged","Ma công":"Magic","Phản đòn":"Counter","Khám phá":"Explore","Nhật ký lữ hành":"Traveler's Journal","Tin trên":"News from the","đường.":"road.","Bài viết mới, tin tức cập nhật và sự kiện đang diễn ra ở thế giới Lữ Hành.":"New posts, updates and current events in the world of Lữ Hành.","Bài viết mới":"New posts","Bật JavaScript để xem bài mới, hoặc":"Turn on JavaScript to see new posts, or","mở danh sách bài viết":"open the post list","Đang kết nối nhật ký…":"Connecting to the journal…","Xem tất cả bài viết":"See all posts","Bốn hệ · Một hành trình":"Four styles · One journey","Chọn lối":"Choose your","chiến đấu.":"fighting style.","Mỗi hệ một nhịp giao tranh. Trang bị và điểm tiềm năng sẽ quyết định bạn đi xa đến đâu.":"Each style has its own rhythm. Your gear and stat points decide how far you go.","Áp sát · Trực diện":"Close in · Head-on","Hệ đánh gần":"Melee","Kiếm, đao, thương và khiên. Lao vào tâm trận, chịu đòn và trả đòn bằng sức nặng của thép.":"Swords, sabers, spears and shields. Charge into the thick of battle, take the hits and strike back with the weight of steel.","Sức mạnh":"Strength","Sức khỏe":"Vitality","Công":"ATK","Thủ":"DEF","Tầm":"Range","Độ khó":"Difficulty","Cự ly · Cơ động":"Distance · Mobility","Hệ đánh xa":"Ranged","Cung và nỏ. Giữ khoảng cách, chọn chỗ đứng, buông dây đúng nhịp trước khi kẻ địch kịp áp sát.":"Bows and crossbows. Keep your distance, pick your ground and loose your shot before the enemy closes in.","Nhanh nhẹn":"Agility","Cơ động":"Mobility","Phép thuật · Ngũ hành":"Spells · Five Elements","Hệ ma công":"Magic","Gậy phép và sách ngũ hành. Hỏa thiêu đốt, Thủy hồi mana, Mộc hồi máu — sức mạnh nằm ở nhịp kết hợp chiêu.":"Staves and books of the Five Elements. Fire burns, Water restores MP, Wood restores HP — the power lies in how you combine your skills.","Trí tuệ":"Intellect","Kiên thủ · Phản kích":"Hold firm · Strike back","Hệ phản đòn":"Counter","Khiên vững cùng sách Thổ, sách Kim. Đứng yên giữa vòng vây, giảm sát thương và để đòn của kẻ địch dội ngược về chính chúng.":"A sturdy shield with Earth and Metal books. Stand firm when surrounded, reduce damage and send the enemy's blows right back at them.","Hướng dẫn tân thủ":"Beginner's Guide","Bốn bước":"Four steps","lên đường.":"to set out.","Chơi ngay trên trình duyệt, máy tính hay điện thoại cầm dọc đều được.":"Play right in your browser — on a computer or a phone held upright.","Tạo nhân vật":"Create a character","Đặt tên, chia điểm tiềm năng vào Sức mạnh, Nhanh nhẹn, Sức khỏe và Trí tuệ.":"Pick a name and spend stat points on Strength, Agility, Vitality and Intellect.","Khám phá làng":"Explore the village","Gặp dân làng Thanh Mộc, nhận nhiệm vụ đầu tiên và làm quen bản đồ.":"Meet the people of Thanh Mộc, take your first quest and learn the map.","Ra trận":"Head into battle","Bước khỏi vùng an toàn, săn quái, nhặt chiến lợi phẩm và lên cấp.":"Step out of the safe zone, hunt monsters, collect loot and level up.","Giao thương":"Trade","Mua bán ở cửa hàng, ký gửi ở chợ phiên, thuê thêm bạn đồng hành.":"Buy and sell in shops, consign at the market and hire companions.","Toàn bộ bài hướng dẫn":"All guides","Người lữ khách":"The traveler","và con đường.":"and the road.","Ở rìa núi rừng có một ngôi làng nhỏ tên Thanh Mộc. Người già trong làng vẫn kể về những vùng đất phía xa: sa mạc nuốt chửng đoàn buôn, núi tuyết chẳng bao giờ tan và những hang động không có đáy.":"At the edge of the mountain forest lies a small village called Thanh Mộc. The elders still tell of faraway lands: a desert that swallows caravans, snow that never melts and caves without a bottom.","Bạn là một lữ khách vừa dừng chân nơi đây. Hành trang còn mỏng, nhưng con đường thì rộng mở — mỗi bước đi sẽ viết thêm một trang cho câu chuyện của riêng bạn.":"You are a traveler who has just stopped here. Your pack is light, but the road is wide open — every step writes another page of your own story.","Đọc cốt truyện":"Read the story","Khởi đầu":"The beginning","Làng Thanh Mộc":"Thanh Mộc Village","Mái nhà, bếp lửa và những người dân hiền lành. Nơi duy nhất bạn không phải rút vũ khí.":"Roofs, hearths and gentle folk. The one place you never need to draw your weapon.","Chương I":"Chapter I","Sa mạc":"Sa mạc · Desert","Cát bỏng, gió khô và những kẻ săn mồi ẩn dưới cồn cát.":"Scorching sand, dry wind and predators hiding beneath the dunes.","Chương II":"Chapter II","Núi tuyết":"Núi tuyết · Snow Mountain","Đỉnh núi phủ trắng quanh năm, nơi cái lạnh cũng là kẻ thù.":"Peaks white all year round, where the cold itself is an enemy.","Chương III":"Chapter III","Hang động":"Hang động · Caves","Bóng tối sâu hun hút, giữ những bí mật chưa ai mang ra ánh sáng.":"Bottomless darkness, holding secrets no one has brought to light.","Bảng vàng lữ khách":"Travelers' Hall of Fame","Bảng":"The","xếp hạng.":"rankings.","Một trăm lữ khách đứng đầu toàn máy chủ. Số liệu làm mới mỗi 10 phút.":"The top one hundred travelers on the server. Refreshed every 10 minutes.","Cao thủ":"Champions","cấp độ":"level","Phú hộ":"Wealthiest","vàng · hồng ngọc":"gold · rubies","Xếp theo":"Sort by","Xem đủ 100 người":"Show all 100","Lối mòn đang đợi":"The trail is waiting","Đường đã mở.":"The road is open.","Còn bạn?":"Are you?","Vào game ngay":"Play now","Gửi lời":"Send word","đến trạm dịch.":"to the post station.","Báo lỗi, góp ý cân bằng hay hợp tác — mọi lá thư đều được đọc.":"Bug reports, balance feedback or partnerships — every letter gets read.","Fanpage Lữ Hành":"Lữ Hành Fanpage","Góp ý, báo lỗi":"Feedback & bugs","Nhắn tin nhanh":"Quick message","Video lối chơi":"Gameplay videos","Kênh liên hệ sẽ sớm được cập nhật. Hẹn gặp bạn trong game!":"Contact channels are coming soon. See you in the game!","Về đầu trang":"Back to top","Tất cả bài viết":"All posts","Lữ Hành - iKyNa, trang chủ":"Lữ Hành - iKyNa, home","Điều hướng chính":"Main navigation","Điều hướng nhanh":"Quick navigation","Lữ khách dừng chân bên căn lều giữa núi rừng lúc hoàng hôn":"A traveler resting by a tent in the mountain forest at dusk","Bốn hệ chiến đấu":"Four fighting styles","Cuộn xuống":"Scroll down","Chuyên mục":"Categories","Lối chơi":"Gameplay","trên":"of","Kiếm thép":"Steel sword","Cung săn":"Hunting bow","Gậy ngọc":"Jade staff","Khiên đồng":"Bronze shield","Chọn hệ":"Choose a style","Hệ trước":"Previous style","Hệ tiếp theo":"Next style","Chọn bảng":"Choose a board","Tìm kiếm Blog này":"Search this blog","Bài đăng trên Blog":"Blog posts","Giới thiệu về tôi":"About me","Nhãn":"Labels","Lữ Hành - iKyNa: game nhập vai phiêu lưu chơi ngay trên trình duyệt. Bốn hệ chiến đấu, làng Thanh Mộc, sa mạc, núi tuyết và hang động.":"Lữ Hành - iKyNa: an adventure RPG you play right in your browser. Four fighting styles, Thanh Mộc Village, deserts, snowy peaks and caves.","Chơi bằng tiếng Anh":"Play in English","Chơi bằng tiếng Việt":"Play in Vietnamese"};
 var VI=/[àáạảãâầấậẩẫăằắặẳẵèéẹẻẽêềếệểễìíịỉĩòóọỏõôồốộổỗơờớợởỡùúụủũưừứựửữỳýỵỷỹđ]/i,LET=/[\p{L}\p{M}]/u,byFirst={},cache={};
 function fw(s){var m=/^[\p{L}\p{M}]+/u.exec(s);return m?m[0]:'';}
 Object.keys(D).sort(function(a,b){return b.length-a.length;}).forEach(function(k){var w=fw(k);if(w)(byFirst[w]=byFirst[w]||[]).push(k);});
 function tr(s){if(!s||!VI.test(s))return s;if(cache[s]!==undefined)return cache[s];var t=s.trim(),out;
   if(D[t]!==undefined)out=s.replace(t,function(){return D[t];});
   else{out='';var i=0;while(i<s.length){var ch=s[i];if(LET.test(ch)&&(i===0||!LET.test(s[i-1]))){var w=fw(s.slice(i,i+40)),c=byFirst[w],hit=null;if(c)for(var j=0;j<c.length;j++){var k=c[j];if(s.substr(i,k.length)===k&&!LET.test(s[i+k.length]||'')){hit=k;break;}}if(hit){out+=D[hit];i+=hit.length;continue;}out+=w;i+=w.length;continue;}out+=ch;i++;}}
   cache[s]=out;return out;}
 var SKIP='script,style,textarea,input,[data-noi18n],#lh-feed h3,#lh-feed p,.lh-rk-name,.lh-rk-podium .lh-rk-name,.post-body,.post-title,.entry-title,.post-header,.comments,.post-snippet,.snippet-item,.post-filter-message';
 function fixEl(el){if(el.closest&&el.closest(SKIP))return true;['title','aria-label','alt','placeholder'].forEach(function(a){var v=el.getAttribute&&el.getAttribute(a);if(v&&VI.test(v)){var o=tr(v);if(o!==v)el.setAttribute(a,o);}});return false;}
 function fixText(n){var p=n.parentNode;if(!p||(p.closest&&p.closest(SKIP)))return;var o=tr(n.data);if(o!==n.data)n.data=o;}
 function walk(r){if(r.nodeType===3){if(VI.test(r.data))fixText(r);return;}if(r.nodeType!==1)return;if(fixEl(r))return;var w=document.createTreeWalker(r,NodeFilter.SHOW_TEXT|NodeFilter.SHOW_ELEMENT),n;while((n=w.nextNode())){if(n.nodeType===3){if(VI.test(n.data))fixText(n);}else if(n.closest&&n.closest(SKIP)){}else fixEl(n);}}
 function startTr(){document.documentElement.lang='en';if(/^Lữ Hành/.test(document.title))document.title=document.title.replace(/·.*$/,'').trim();walk(document.body);
   new MutationObserver(function(l){l.forEach(function(r){if(r.type==='characterData'){if(VI.test(r.target.data))fixText(r.target);}else r.addedNodes.forEach(walk);});}).observe(document.body,{childList:true,subtree:true,characterData:true});}
})();
//

head.b:skin:
/*! normalize.css v3.0.1 | MIT License | git.io/normalize */html{font-family:sans-serif;-ms-text-size-adjust:100%;-webkit-text-size-adjust:100%}body{margin:0}article,aside,details,figcaption,figure,footer,header,hgroup,main,nav,section,summary{display:block}audio,canvas,progress,video{display:inline-block;vertical-align:baseline}audio:not([controls]){display:none;height:0}[hidden],template{display:none}a{background:transparent}a:active,a:hover{outline:0}abbr[title]{border-bottom:1px dotted}b,strong{font-weight:bold}dfn{font-style:italic}h1{font-size:2em;margin:.67em 0}mark{background:#ff0;color:#000}small{font-size:80%}sub,sup{font-size:75%;line-height:0;position:relative;vertical-align:baseline}sup{top:-0.5em}sub{bottom:-0.25em}img{border:0}svg:not(:root){overflow:hidden}figure{margin:1em 40px}hr{-moz-box-sizing:content-box;box-sizing:content-box;height:0}pre{overflow:auto}code,kbd,pre,samp{font-family:monospace,monospace;font-size:1em}button,input,optgroup,select,textarea{color:inherit;font:inherit;margin:0}button{overflow:visible}button,select{text-transform:none}button,html input[type="button"],input[type="reset"],input[type="submit"]{-webkit-appearance:button;cursor:pointer}button[disabled],html input[disabled]{cursor:default}button::-moz-focus-inner,input::-moz-focus-inner{border:0;padding:0}input{line-height:normal}input[type="checkbox"],input[type="radio"]{box-sizing:border-box;padding:0}input[type="number"]::-webkit-inner-spin-button,input[type="number"]::-webkit-outer-spin-button{height:auto}input[type="search"]{-webkit-appearance:textfield;-moz-box-sizing:content-box;-webkit-box-sizing:content-box;box-sizing:content-box}input[type="search"]::-webkit-search-cancel-button,input[type="search"]::-webkit-search-decoration{-webkit-appearance:none}fieldset{border:1px solid #c0c0c0;margin:0 2px;padding:.35em .625em .75em}legend{border:0;padding:0}textarea{overflow:auto}optgroup{font-weight:bold}table{border-collapse:collapse;border-spacing:0}td,th{padding:0}
/*
<!-- Constants -->

<Variable name="damionRegular36" description="Damion Regular 36" type="font" default="400 36px Damion, cursive" hideEditor="true"  value="400 36px Damion, cursive"/>
<Variable name="damionRegular62" description="Damion Regular 62" type="font" default="400 62px Damion, cursive" hideEditor="true"  value="400 62px Damion, cursive"/>
<Variable name="playfairDisplayBlack28" description="Playfair Display Black 28" type="font" default="900 28px Playfair Display, serif" hideEditor="true"  value="900 28px Playfair Display, serif"/>
<Variable name="playfairDisplayBlack36" description="Playfair Display Black 36" type="font" default="900 36px Playfair Display, serif" hideEditor="true"  value="900 36px Playfair Display, serif"/>
<Variable name="playfairDisplayBlack44" description="Playfair Display Black 44" type="font" default="900 44px Playfair Display, serif" hideEditor="true"  value="900 44px Playfair Display, serif"/>
<Variable name="robotoNormal15" description="Roboto Normal 15" type="font" default="15px Roboto, sans-serif" hideEditor="true"  value="15px Roboto, sans-serif"/>
<Variable name="robotoNormal16" description="Roboto Normal 16" type="font" default="16px Roboto, sans-serif" hideEditor="true"  value="16px Roboto, sans-serif"/>
<Variable name="robotoLightItalic15" description="Roboto Light Italic 15" type="font" default="italic 300 15px Roboto, sans-serif" hideEditor="true"  value="italic 300 15px Roboto, sans-serif"/>
<Variable name="robotoBold22" description="Roboto Bold 22" type="font" default="bold 22px Roboto, sans-serif" hideEditor="true"  value="bold 22px Roboto, sans-serif"/>
<Variable name="robotoBold30" description="Roboto Bold 30" type="font" default="bold 30px Roboto, sans-serif" hideEditor="true"  value="bold 30px Roboto, sans-serif"/>
<Variable name="robotoBold45" description="Roboto Bold 45" type="font" default="bold 45px Roboto, sans-serif" hideEditor="true"  value="bold 45px Roboto, sans-serif"/>

<!-- Variable definitions -->

<Variable name="keycolor" description="Main Color" type="color" default="#2196f3"  value="#d8b46c"/>
<Variable name="startSide" description="Start side in blog language" type="automatic" default="left" hideEditor="true" />
<Variable name="endSide" description="End side in blog language" type="automatic" default="right" hideEditor="true" />

<Group description="Page Text">
  <Variable name="body.text.font" description="Font"
      type="font"
      default="$(robotoNormal15)"  value="15px 'Be Vietnam Pro', sans-serif"/>
  <Variable name="body.text.color" description="Color"
      type="color"
      default="#757575"  value="#cfd3c5"/>
</Group>

<Group description="Backgrounds">
  <Variable name="body.background.height" description="Background height"
      type="length"
      min="420px"
      max="640px"
      default="480px"  value="480px"/>
  <Variable name="body.background" description="Background"
      color="$(body.background.color)"
      type="background"
      default="$(color) none repeat scroll top left"  value="$(color) url(https://lh3.googleusercontent.com/d/1WL5mtyCDQA3NN498XU5BNCmOuOAWVgKi) no-repeat scroll top center"/>
  <Variable name="body.background.color" description="Body background color"
      type="color"
      default="#eee"  value="#0b1410"/>
  <Variable name="posts.background.color" description="Post background color"
      type="color"
      default="#fff"  value="#111d17"/>
  <Variable name="body.background.blur" description="Background blur"
      type="length"
      min="0px"
      max="50px"
      default="0px"  value="0px"/>
</Group>

<Group description="Links">
  <Variable name="body.link.color" description="Link color"
      type="color"
      default="#2196f3"  value="#d8b46c"/>
  <Variable name="body.link.visited.color" description="Visited link color"
      type="color"
      default="$(body.link.color)"  value="#d8b46c"/>
  <Variable name="body.link.hover.color" description="Link Hover Color"
      type="color"
      default="$(body.link.color)"  value="#f2dca6"/>
</Group>

<Group description="Blog title" selector="div.widget.Header">
  <Variable name="blog.title.font" description="Font"
      type="font"
      default="$(robotoBold45)"  value="600 54px 'Cormorant Garamond', serif"/>
  <Variable name="blog.title.color" description="Color"
      type="color"
      default="#fff"  value="#f2dca6"/>
  <Variable name="header.icons.color"
      description="Background icons color"
      type="color"
      default="#fff"  value="#f2dca6"/>
</Group>

<Group description="Tabs text" selector="div.widget.PageList">
  <Variable name="tabs.font" description="Font"
      type="font"
      family="$(robotoNormal15.family)"
      size="$(robotoNormal15.size)"
      default="700 normal $(size) $(family)"  value="700 normal $(size) $(family)"/>
  <Variable name="tabs.color" description="Text color"
      type="color"
      default="#ccc"  value="#d9dccf"/>
  <Variable name="tabs.selected.color" description="Selected color"
      type="color"
      default="#fff"  value="#f2dca6"/>
  <Variable name="tabs.overflow.background.color" description="Popup background color"
      type="color"
      default="$(posts.background.color)"  value="#111d17"/>
  <Variable name="tabs.overflow.color" description="Popup text color"
      type="color"
      default="$(posts.text.color)"  value="#cfd3c5"/>
  <Variable name="tabs.overflow.selected.color" description="Popup selected color"
      type="color"
      default="$(posts.title.color)"  value="#f2dca6"/>
</Group>

<Group description="Posts" selector="div.widget.Blog">
  <Variable name="posts.title.color" description="Post title color"
      type="color"
      default="#212121"  value="#f3ead2"/>
  <Variable name="posts.title.font" description="Post title font"
      type="font"
      default="$(robotoBold22)"  value="600 34px 'Cormorant Garamond', serif"/>
  <Variable name="posts.stream.title.font" description="Post title stream font"
      type="font"
      default="$(robotoBold30)"  value="600 32px 'Cormorant Garamond', serif"/>
