(function(){
 'use strict';
 var root=document.getElementById('lh-home');if(!root)return;
 if(!Element.prototype.replaceChildren)Element.prototype.replaceChildren=function(){while(this.firstChild)this.removeChild(this.firstChild);for(var i=0;i<arguments.length;i++)this.append(arguments[i]);}; root.classList.add('lh-js'); try{run();}catch(err){root.classList.remove('lh-js');if(window.console)console.error('lh-home',err);} function run(){
 document.title='Lữ Hành - iKyNa';
 var FALLBACK='https://lh3.googleusercontent.com/d/1IqboleL9d1KowRwwD9K4aib0mOXgnhG7';
 var LABELS=['Tin tức','Sự kiện','Hướng dẫn','Cốt truyện'];
 var reduce=!!(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches);
 function $(s){return root.querySelector(s);}
 function $$(s){return Array.prototype.slice.call(root.querySelectorAll(s));}
 function el(tag,cls,text){var n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;}

 /* Ảnh lỗi: dùng ảnh dự phòng, logo lỗi thì hiện chữ */
 function guard(img){img.addEventListener('error',function(){
   if(img.closest('.lh-brand')){img.replaceWith(el('span','lh-brand-text','Lữ Hành'));return;}
   if(img.classList.contains('lh-weapon')||img.dataset.fb==='1'){img.hidden=true;return;}
   img.dataset.fb='1';img.src=FALLBACK;});}
 $$('img').forEach(guard);

 /* Thanh menu: nền đặc khi cuộn, đánh dấu mục đang xem */
 var nav=$('#lh-nav');
 function onScroll(){nav.classList.toggle('is-solid',(window.scrollY||window.pageYOffset)>40);}
 window.addEventListener('scroll',onScroll,{passive:true});onScroll();
 var links=$$('[data-sec]');
 function mark(id){links.forEach(function(a){a.classList.toggle('is-active',a.dataset.sec===id);if(a.dataset.sec===id)a.setAttribute('aria-current','true');else a.removeAttribute('aria-current');});}
 mark('lh-top');
 links.forEach(function(a){if(a.dataset.sec==='lh-top')a.addEventListener('click',function(e){e.preventDefault();window.scrollTo({top:0,behavior:reduce?'auto':'smooth'});});});
 if('IntersectionObserver' in window){
   var spy=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting)mark(e.target.id);});},{rootMargin:'-45% 0px -50% 0px'});
   ['lh-top','lh-news','lh-styles','lh-guide','lh-story','lh-rank','lh-contact'].forEach(function(id){var s=document.getElementById(id);if(s)spy.observe(s);});
 }

 /* Hiện dần khi cuộn tới */
 var rv=$$('.lh-reveal');
 if('IntersectionObserver' in window&&!reduce){
   var ro=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('is-in');ro.unobserve(e.target);}});},{threshold:.12,rootMargin:'0px 0px -6% 0px'});
   rv.forEach(function(n){ro.observe(n);});
 }else rv.forEach(function(n){n.classList.add('is-in');});

 /* ===== Bài viết: lấy từ feed Blogspot theo nhãn ===== */
 var feed=$('#lh-feed'),count=$('#lh-count'),more=$('#lh-more'),tabs=$$('.lh-tab'),cache={},req=0,active='';
 function safeURL(s){try{var u=new URL(s,location.origin);return /^https?:$/.test(u.protocol)?u.href:'';}catch(e){return '';}}
 function plain(s){var d=document.createElement('div');d.innerHTML=String(s||'').replace(/<(script|style)[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]*>/g,' ');return (d.textContent||'').replace(/\s+/g,' ').trim();}
 function fixImage(url){var u=safeURL(url);if(!u)return '';var m=u.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?(?:export=\w+&)?id=)([\w-]+)/);if(m)return 'https://lh3.googleusercontent.com/d/'+m[1];return u.replace(/\/(s\d+(?:-[^/]*)?|w\d+-h\d+(?:-[^/]*)?)\//,'/s1000/').replace(/=s\d+(-c)?$/,'=s1000');}
 function parse(entry,label){
   var link=(entry.link||[]).filter(function(l){return l.rel==='alternate';})[0],url=safeURL(link&&link.href);if(!url)return null;
   var raw=(entry.content&&entry.content.$t)||(entry.summary&&entry.summary.$t)||'',m=raw.match(/<img\b[^>]*\bsrc\s*=\s*["']([^"']+)["']/i);
   var cats=(entry.category||[]).map(function(c){return c.term;});
   var date=new Date(entry.published&&entry.published.$t);
   return {url:url,title:plain(entry.title&&entry.title.$t)||'Bài viết',text:plain(raw).slice(0,260),
     img:fixImage((entry.media$thumbnail&&entry.media$thumbnail.url)||(m&&m[1]))||FALLBACK,
     cat:label||cats.filter(function(c){return LABELS.indexOf(c)>-1;})[0]||'Nhật ký',date:isNaN(date.getTime())?null:date};
 }
 function meta(p){var box=el('div','lh-meta');box.append(el('span','lh-chip',p.cat));
   if(p.date){var t=el('time','',p.date.toLocaleDateString((window.LH_HOME_LOC||'vi-VN'),{day:'2-digit',month:'2-digit',year:'numeric',timeZone:'Asia/Ho_Chi_Minh'}));t.dateTime=p.date.toISOString();box.append(t);}return box;}
 function pic(p,w){var img=el('img');img.src=p.img;img.alt='';img.loading='lazy';img.decoding='async';img.width=w;img.height=Math.round(w*.6);img.referrerPolicy='no-referrer';guard(img);return img;}
 function status(text,retry,busy){feed.replaceChildren();var box=el('div','lh-status');if(busy)box.append(el('span','lh-spin'));box.append(document.createTextNode(text));
   if(retry){var b=el('button','','Thử tải lại');b.type='button';b.addEventListener('click',function(){delete cache[active];load(active);});box.append(b);}feed.append(box);}
 function render(entries,label){
   feed.replaceChildren();feed.setAttribute('aria-busy','false');
   var posts=entries.map(function(e){return parse(e,label);}).filter(Boolean);
   if(!posts.length){status(label?'Chưa có bài viết trong mục '+label+'.':'Nhật ký đang chờ câu chuyện đầu tiên.');count.textContent='Chưa có bài viết';return;}
   var f=posts[0],art=el('article','lh-feature'),a=el('a'),body=el('div','lh-feature-body');a.href=f.url;
   body.append(meta(f),el('h3','',f.title),el('p','',f.text));a.append(pic(f,900),body);art.append(a);feed.append(art);
   if(posts.length>1){var list=el('div','lh-list');posts.slice(1,5).forEach(function(p){var it=el('article','lh-item'),b=el('a'),th=el('div','lh-thumb'),tx=el('div');b.href=p.url;th.append(pic(p,240));tx.append(meta(p),el('h3','',p.title));b.append(th,tx);it.append(b);list.append(it);});feed.append(list);}
   count.textContent=posts.length+' bài'+(label?' · '+label:' mới nhất');
 }
 function getFeed(label){return new Promise(function(resolve,reject){
   var s=document.createElement('script'),name='lhFeed_'+Date.now()+'_'+Math.random().toString(36).slice(2),timer;
   function clean(){clearTimeout(timer);s.remove();delete window[name];}
   window[name]=function(data){clean();if(!data||!data.feed){reject(new Error('feed'));return;}resolve(data.feed.entry||[]);};
   s.src='/feeds/posts/default'+(label?'/-/'+encodeURIComponent(label):'')+'?alt=json-in-script&max-results=8&orderby=published&callback='+name;
   s.onerror=function(){clean();reject(new Error('feed'));};
   timer=setTimeout(function(){s.remove();window[name]=function(){delete window[name];};reject(new Error('timeout'));},15000);
   document.head.append(s);});}
 function load(label){
   active=label;var id=++req;more.href=label?'/search/label/'+encodeURIComponent(label):'/search';
   var tab=tabs.filter(function(t){return t.dataset.label===label;})[0];if(tab)feed.setAttribute('aria-labelledby',tab.id);
   if(cache[label]){render(cache[label],label);return;}
   feed.setAttribute('aria-busy','true');status('Đang tải bài viết…',false,true);count.textContent='Đang tải '+(label||'bài viết mới')+'…';
   getFeed(label).then(function(entries){cache[label]=entries;if(id===req)render(entries,label);},function(){if(id!==req)return;feed.setAttribute('aria-busy','false');status('Chưa tải được bài viết. Thử lại hoặc mở danh sách bên dưới.',true);count.textContent='Kết nối tạm gián đoạn';});
 }
 function wire(items,activate){items.forEach(function(t,i){
   t.addEventListener('click',function(){activate(i,true);});
   t.addEventListener('keydown',function(e){var j=i;if(e.key==='ArrowRight')j=(i+1)%items.length;else if(e.key==='ArrowLeft')j=(i+items.length-1)%items.length;else if(e.key==='Home')j=0;else if(e.key==='End')j=items.length-1;else return;e.preventDefault();items[j].focus();activate(j,true);});});}
 function select(items,i){items.forEach(function(t,k){t.setAttribute('aria-selected',String(k===i));t.tabIndex=k===i?0:-1;});}
 wire(tabs,function(i){select(tabs,i);load(tabs[i].dataset.label);});
 load('');

 /* ===== Slide lối chơi kiểu điện ảnh ===== */
 var stage=$('#lh-stage'),slides=$$('.lh-slide'),dots=$$('.lh-dot'),idx=0,DUR=7000,hold={hover:false,focus:false,view:true};
 stage.style.setProperty('--dur',DUR+'ms');
 if(reduce)stage.classList.add('is-static','is-paused');
 function show(n){
   n=(n+slides.length)%slides.length;idx=n;
   slides.forEach(function(s,k){var on=k===n;s.classList.toggle('is-active',on);s.setAttribute('aria-hidden',String(!on));if('inert' in s)s.inert=!on;});
   select(dots,n);
   var bar=dots[n].querySelector('i');bar.style.animation='none';void bar.offsetWidth;bar.style.animation='';
 }
 function sync(){if(!reduce)stage.classList.toggle('is-paused',hold.hover||hold.focus||!hold.view||document.hidden);}
 stage.addEventListener('animationend',function(e){if(e.animationName==='lh-progress'&&!reduce)show(idx+1);});
 wire(dots,function(i){show(i);});
 $('#lh-prev').addEventListener('click',function(){show(idx-1);});
 $('#lh-next').addEventListener('click',function(){show(idx+1);});
 stage.addEventListener('pointerenter',function(e){if(e.pointerType==='mouse'){hold.hover=true;sync();}});
 stage.addEventListener('pointerleave',function(){hold.hover=false;sync();});
 stage.addEventListener('focusin',function(){hold.focus=true;sync();});
 stage.addEventListener('focusout',function(e){if(!stage.contains(e.relatedTarget)){hold.focus=false;sync();}});
 document.addEventListener('visibilitychange',sync);
 if('IntersectionObserver' in window)new IntersectionObserver(function(es){hold.view=es[0].isIntersecting;sync();},{threshold:.35}).observe(stage);
 var x0=null,y0=0;
 stage.addEventListener('pointerdown',function(e){if(e.target.closest('button'))return;x0=e.clientX;y0=e.clientY;});
 stage.addEventListener('pointerup',function(e){if(x0===null)return;var dx=e.clientX-x0,dy=e.clientY-y0;x0=null;if(Math.abs(dx)>50&&Math.abs(dx)>Math.abs(dy))show(idx+(dx<0?1:-1));});
 stage.addEventListener('pointercancel',function(){x0=null;});
 $$('.lh-hero-classes [data-go]').forEach(function(b){b.addEventListener('click',function(){show(+b.dataset.go);document.getElementById('lh-styles').scrollIntoView({behavior:reduce?'auto':'smooth'});});});
 show(0);sync();

 /* ===== Bảng xếp hạng: gọi máy chủ game (lệnh rank), chỉ tải khi cuộn gần tới ===== */
 (function(){
  var sec=document.getElementById('lh-rank');if(!sec)return;
  var api=sec.getAttribute('data-api'),board=$('#lh-rk-board'),note=$('#lh-rk-note'),more=$('#lh-rk-more'),sortBox=$('#lh-rk-sort'),rtabs=$$('.lh-rk-tab'),sorts=$$('#lh-rk-sort button');
  var data=null,mode='level',by='gold',full=false,busy=false,KEY='lh-rank-v1';
  function fmt(n){return Number(n||0).toLocaleString((window.LH_HOME_LOC||'vi-VN'));}
  function list(){return mode==='level'?data.level:(by==='ruby'?data.ruby:data.gold);}
  function main(p){return mode==='level'?'Cấp '+fmt(p.cap):(by==='ruby'?fmt(p.hn)+' hồng ngọc':fmt(p.vang)+' vàng');}
  function sub(p){return mode==='level'?fmt(p.vang)+' vàng':'Cấp '+fmt(p.cap);}
  function msg(text,retry,spin){board.replaceChildren();var b=el('div','lh-rk-status');if(spin)b.append(el('span','lh-rk-spin'));b.append(document.createTextNode(text));
    if(retry){var r=el('button','','Thử tải lại');r.type='button';r.addEventListener('click',function(){load(true);});b.append(r);}board.append(b);}
  function cell(cls,text){return el('span',cls,text);}
  function render(){
    if(!data)return;board.setAttribute('aria-busy','false');board.replaceChildren();
    var L=list()||[];if(!L.length){msg('Bảng vàng còn trống. Hãy là lữ khách đầu tiên ghi tên!');more.hidden=true;return;}
    var pod=el('div','lh-rk-podium');
    L.slice(0,3).forEach(function(p,i){var c=el('div','lh-rk-p r'+(i+1)),nm=el('b','',p.ten);nm.title=p.ten;c.append(el('span','lh-rk-medal',String(i+1)),nm,el('span','lh-rk-big',main(p)),el('span','lh-rk-sub',sub(p)));pod.append(c);});
    board.append(pod);
    if(L.length>3){
      var ul=el('div','lh-rk-list'),gold=mode==='rich'&&by==='gold',ruby=mode==='rich'&&by==='ruby',head=el('div','lh-rk-row is-head');
      head.append(cell('','#'),cell('','Nhân vật'),cell('lh-rk-v'+(mode==='rich'?' lh-rk-x':''),'Cấp'),cell('lh-rk-v','Vàng'),cell('lh-rk-v'+(mode==='level'?' lh-rk-x':''),'Hồng ngọc'));ul.append(head);
      L.slice(3,full?100:10).forEach(function(p,i){var r=el('div','lh-rk-row'),nm=el('span','lh-rk-name');nm.append(el('i','lh-rk-g'+(p.gt==='f'?' f':'')),el('span','',p.ten));nm.title=p.ten;
        r.append(cell('lh-rk-n',String(i+4)),nm,cell('lh-rk-v'+(mode==='level'?' is-key':' lh-rk-x'),fmt(p.cap)),cell('lh-rk-v'+(gold?' is-key':''),fmt(p.vang)),cell('lh-rk-v'+(ruby?' is-key':'')+(mode==='level'?' lh-rk-x':''),fmt(p.hn)));ul.append(r);});
      board.append(ul);
    }
    more.hidden=full||L.length<=10;
    var t=new Date(data.at||Date.now());note.textContent=fmt(data.total)+' lữ khách trên máy chủ · cập nhật '+t.toLocaleTimeString((window.LH_HOME_LOC||'vi-VN'),{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Ho_Chi_Minh'});
  }
  function load(force){
    if(busy)return;busy=true;
    if(!force){try{var c=JSON.parse(sessionStorage.getItem(KEY)||'null');if(c&&c.ok&&Date.now()-c._t<300000){data=c;busy=false;render();return;}}catch(e){}}
    board.setAttribute('aria-busy','true');msg('Đang mở bảng vàng…',false,true);
    var ctl=window.AbortController?new AbortController():null,timer=setTimeout(function(){if(ctl)ctl.abort();},25000);
    fetch(api+'?p='+encodeURIComponent(JSON.stringify({action:'rank'})),ctl?{signal:ctl.signal}:{}).then(function(r){return r.json();}).then(function(d){
      clearTimeout(timer);busy=false;if(!d||!d.ok)throw new Error((d&&d.error)||'rank');data=d;try{d._t=Date.now();sessionStorage.setItem(KEY,JSON.stringify(d));}catch(e){}render();
    }).catch(function(){clearTimeout(timer);busy=false;board.setAttribute('aria-busy','false');msg('Chưa lấy được bảng xếp hạng từ máy chủ game.',true);note.textContent='Kết nối tạm gián đoạn';more.hidden=true;});
  }
  wire(rtabs,function(i){select(rtabs,i);mode=rtabs[i].dataset.b;full=false;sortBox.hidden=mode!=='rich';board.setAttribute('aria-labelledby',rtabs[i].id);render();});
  sorts.forEach(function(b){b.addEventListener('click',function(){by=b.dataset.s;full=false;sorts.forEach(function(x){x.setAttribute('aria-pressed',String(x===b));});render();});});
  more.addEventListener('click',function(){full=true;render();});
  if('IntersectionObserver' in window){var io=new IntersectionObserver(function(es){if(es[0].isIntersecting){io.disconnect();load();}},{rootMargin:'600px 0px'});io.observe(sec);}else load();
 })();

 /* Liên hệ: ẩn kênh chưa điền link */
 var shown=0;$$('.lh-channel').forEach(function(a){var h=(a.getAttribute('href')||'').trim();if(!h||h==='#'){a.hidden=true;}else{shown++;if(/^mailto:|^tel:/i.test(h))a.removeAttribute('target');}});
 $('#lh-channels-empty').hidden=shown>0;
 $('#lh-year').textContent=new Date().getFullYear(); }
})();
